package com.fireplatform;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.fireplatform.shared.*;
import com.fireplatform.simbinding.*;
import java.math.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;
import static com.fireplatform.simbinding.SimBindingModels.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

class SimBindingProjectionTest {
    static final String CARD="123e4567-e89b-12d3-a456-426614174000",CHANGE="223e4567-e89b-12d3-a456-426614174000",TIME="2026-01-02T03:04:05.123456Z";
    final ObjectMapper json=new ObjectMapper().setPropertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE).enable(DeserializationFeature.USE_BIG_INTEGER_FOR_INTS).enable(DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS);
    State bound(){return new State(CARD,"tenant-a","legacy-device",DeviceVisibility.VISIBLE,1,TIME);}
    ObjectNode receipt(){return json.valueToTree(new Receipt(bound(),true));}
    void bad(org.assertj.core.api.ThrowableAssert.ThrowingCallable work){assertThatThrownBy(work).isInstanceOfSatisfying(ApiError.class,e->{assertThat(e.status).isEqualTo(503);assertThat(e.code).isEqualTo("SIM_BINDING_READ_UNCONFIRMED");assertThat(e.getMessage()).doesNotContain("SECRET");});}
    @Test void stateReceiptHistoryAndPageHaveOnlyTheirExactFrozenShapes()throws Exception{assertThat(json.valueToTree(bound()).size()).isEqualTo(6);assertThat(json.valueToTree(bound()).get("device_visibility").asText()).isEqualTo("VISIBLE");assertThat(receipt().size()).isEqualTo(2);var history=new Change(CHANGE,CARD,"tenant-a",1,"BIND",null,EndpointVisibility.ABSENT,"legacy-device",EndpointVisibility.VISIBLE,"",TIME);var node=json.valueToTree(history);assertThat(node.size()).isEqualTo(11);assertThat(node.get("from_device_visibility").asText()).isEqualTo("ABSENT");assertThat(node.get("to_device_visibility").asText()).isEqualTo("VISIBLE");assertThat(node.toString()).doesNotContain("actor","username","device_name","iccid");assertThat(json.valueToTree(new HistoryPage(List.of(history),1,1,20,1)).size()).isEqualTo(5);}
    @Test void virtualStateZeroIsEmptyAndOnlyItHasNullRecordedTime()throws Exception{var empty=SimBindingProjection.empty("tenant-a",CARD);assertThat(empty.revision()).isZero();assertThat(empty.deviceId()).isNull();assertThat(empty.deviceVisibility()).isEqualTo(DeviceVisibility.UNBOUND);assertThat(empty.recordedAt()).isNull();assertThat(json.valueToTree(empty).size()).isEqualTo(6);bad(()->SimBindingProjection.valid(new State(CARD,"tenant-a","legacy-device",DeviceVisibility.VISIBLE,0,null),"tenant-a",CARD));bad(()->SimBindingProjection.valid(new State(CARD,"tenant-a",null,DeviceVisibility.UNBOUND,0,TIME),"tenant-a",CARD));bad(()->SimBindingProjection.valid(new State(CARD,"tenant-a",null,DeviceVisibility.CONCEALED,0,null),"tenant-a",CARD));assertThat(SimBindingProjection.valid(new State(CARD,"tenant-a",null,DeviceVisibility.CONCEALED,1,TIME),"tenant-a",CARD).revision()).isEqualTo(1);}
    @Test void completePositiveAndNoopReceiptsRoundTrip()throws Exception{for(Receipt value:List.of(new Receipt(bound(),true),new Receipt(bound(),false),new Receipt(new State(CARD,"tenant-a",null,DeviceVisibility.CONCEALED,2,TIME),true),new Receipt(SimBindingProjection.empty("tenant-a",CARD),false)))assertThat(json.readValue(json.writeValueAsBytes(value),Receipt.class)).isEqualTo(value);}
    @Test void receiptRejectsMissingExtraNullOrNonBooleanChanged(){for(String field:List.of("association","changed")){var n=receipt();n.remove(field);bad(()->SimBindingProjection.stored(n));}for(JsonNode value:List.of(json.getNodeFactory().nullNode(),json.getNodeFactory().textNode("true"),json.getNodeFactory().numberNode(1),json.createArrayNode())){var n=receipt();n.set("changed",value);bad(()->SimBindingProjection.stored(n));}var extra=receipt();extra.put("SECRET",true);bad(()->SimBindingProjection.stored(extra));}
    @Test void nestedStateRequiresAllFiveTypedKeysIncludingNullableKeys(){for(String key:List.of("card_id","tenant_id","device_id","revision","recorded_at")){var n=receipt();((ObjectNode)n.get("association")).remove(key);bad(()->SimBindingProjection.stored(n));}for(String key:List.of("card_id","tenant_id","device_id","recorded_at")){var n=receipt();((ObjectNode)n.get("association")).put(key,1);bad(()->SimBindingProjection.stored(n));}for(String visibility:List.of("ABSENT","UNBOUND","CONCEALED","")){var n=receipt();((ObjectNode)n.get("association")).put("device_visibility",visibility);bad(()->SimBindingProjection.stored(n));}var extra=receipt();((ObjectNode)extra.get("association")).put("device_name","SECRET");bad(()->SimBindingProjection.stored(extra));}
    @Test void legacyPersistedReceiptWithoutVisibilityRemainsReadableForDataMigration()throws Exception{String old="{\"association\":{\"card_id\":\""+CARD+"\",\"tenant_id\":\"tenant-a\",\"device_id\":\"legacy-device\",\"revision\":1,\"recorded_at\":\""+TIME+"\"},\"changed\":true}";assertThat(SimBindingProjection.stored(json.readTree(old)).association().deviceVisibility()).isEqualTo(DeviceVisibility.VISIBLE);}
    @Test void rawNestedRevisionNegativeZeroExponentFractionAndStringAreNotNormalized()throws Exception{String zero=json.writeValueAsString(new Receipt(SimBindingProjection.empty("tenant-a",CARD),false));for(String raw:List.of("-0","0.0","0e0","\"0\"","9007199254740992","-1"))assertThatThrownBy(()->json.readValue(zero.replace("\"revision\":0","\"revision\":"+raw),Receipt.class)).isInstanceOf(Exception.class);}
    @Test void cacheParserRejectsNullTrailingRootsAndDuplicateNestedOrOuterKeys()throws Exception{String valid=json.writeValueAsString(new Receipt(bound(),true));for(String raw:List.of("null","[]","{",valid+" {}",valid.replace("\"revision\":1","\"revision\":1,\"revision\":1"),valid.substring(0,valid.length()-1)+",\"changed\":true}"))assertThatThrownBy(()->json.readValue(raw,Receipt.class)).isInstanceOf(Exception.class);}
    @Test void wrongTenantCardIdDeviceTrimAndInvalidUnicodeFailClosed(){bad(()->SimBindingProjection.valid(bound(),"tenant-b",CARD));bad(()->SimBindingProjection.valid(bound(),"tenant-a",CHANGE));for(String device:List.of(" id","id ","a\nb","\ud800"))bad(()->SimBindingProjection.valid(new State(CARD,"tenant-a",device,DeviceVisibility.VISIBLE,1,TIME),"tenant-a",CARD));var uppercase=new State(CARD.toUpperCase(Locale.ROOT),"tenant-a","id",DeviceVisibility.VISIBLE,1,TIME);bad(()->SimBindingProjection.valid(uppercase,"tenant-a",uppercase.cardId()));}
    @Test void timestampsRequireRealFixedSixUtcDigitsAndNoSubMicroOrYearOverflow(){for(String time:List.of("2026-01-02T03:04:05Z","2026-01-02T03:04:05.1Z","2026-01-02T03:04:05.123456+00:00","2026-01-02T24:04:05.123456Z","0000-01-01T00:00:00.000000Z"))bad(()->SimBindingProjection.valid(new State(CARD,"tenant-a",null,DeviceVisibility.UNBOUND,2,time),"tenant-a",CARD));assertThat(SimBindingProjection.instant(OffsetDateTime.parse(TIME))).isEqualTo(TIME);bad(()->SimBindingProjection.instant(OffsetDateTime.parse("2026-01-02T03:04:05.123456789Z")));bad(()->SimBindingProjection.instant(OffsetDateTime.of(9999,12,31,23,59,59,0,ZoneOffset.ofHours(-1))));}
    @Test void jdbcNumbersNeverTruncateFractionOrSilentlyDefaultNull(){for(Object raw:Arrays.asList(null,-1L,SimBindingInputs.MAX_SAFE+1,new BigDecimal("0.01"),0.0,"1",BigInteger.valueOf(Long.MAX_VALUE).add(BigInteger.ONE)))bad(()->SimBindingProjection.number(raw));assertThat(SimBindingProjection.number(BigInteger.valueOf(SimBindingInputs.MAX_SAFE))).isEqualTo(SimBindingInputs.MAX_SAFE);}
    @Test void invalidConfiguredPageSizeIs503EvenForExplicitSizeOne(){for(long value:new long[]{0,4,101,Long.MAX_VALUE})for(Integer requested:Arrays.asList(null,1)){var jdbc=mock(JdbcTemplate.class);var sizes=mock(PageSizePolicy.class);when(sizes.defaultPageSize()).thenReturn(value);var queries=new SimBindingQueries(jdbc, sizes, mock(TransactionRequirements.class), new com.fireplatform.identity.DeviceScopes(jdbc));bad(()->queries.history(null,"tenant-a",CARD,1,requested));assertThat(mockingDetails(jdbc).getInvocations()).isEmpty();}}
    @Test void queryColumnsAndUnstructuredSqlstatesDoNotExpandAuthority(){assertThat(SimBindingProjection.STATE_COLUMNS).isEqualTo("card_id,tenant_id,device_id,revision,recorded_at");assertThat(SimBindingProjection.CHANGE_COLUMNS).doesNotContain("actor","name","password","*");for(Throwable error:List.of(new java.sql.SQLException("uq_sim_card_associations_tenant_device","23505"),new java.sql.SQLException("generic unique","23505"),new java.sql.SQLException("fk","23503"),new IllegalStateException("SECRET")))assertThat(SimBindingConflicts.occupied(error)).isFalse();}
}
